import javastraw.reader.Dataset;
import javastraw.reader.basics.Chromosome;
import javastraw.reader.block.ContactRecord;
import javastraw.reader.mzd.MatrixZoomData;
import javastraw.reader.type.HiCZoom;
import javastraw.reader.type.NormalizationHandler;
import javastraw.reader.type.NormalizationType;
import javastraw.tools.ExtractingOEDataUtils;
import javastraw.tools.HiCFileTools;

import java.util.List;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.file.Files;
import java.nio.file.Path;

/** Independent fixtures generated by straw/C++/tests/test_v10.py: trans=True, frag=True,
 * plus score=True with f32 bit patterns for (1,1,5). No expected indexes. */
public final class TransExpectedRegression {
    public static void main(String[] args) throws Exception {
        for (String path : args) {
            Dataset dataset = HiCFileTools.extractDatasetForCLT(path, false, true, false);
            Chromosome[] chromosomes = dataset.getChromosomeHandler().getChromosomeArrayWithoutAllByAll();
            MatrixZoomData frag = dataset.getMatrix(chromosomes[0], chromosomes[1])
                .getZoomData(new HiCZoom(HiCZoom.HiCUnit.FRAG, 1));
            close(7.0 / 64, frag.getAverageCount());
            for (int resolution : new int[]{10, 20}) {
                double mean = resolution == 10 ? 7.0 / 56 : 7.0 / 16;
                double product = resolution == 10 ? 6 : 24;
                for (boolean reverse : new boolean[]{false, true}) {
                    MatrixZoomData zd = dataset.getMatrix(chromosomes[reverse ? 1 : 0],
                        chromosomes[reverse ? 0 : 1]).getZoomData(new HiCZoom(HiCZoom.HiCUnit.BP, resolution));
                    close(mean, zd.getAverageCount());
                    for (NormalizationType norm : new NormalizationType[]{NormalizationHandler.NONE, NormalizationHandler.VC}) {
                        List<ContactRecord> records = ExtractingOEDataUtils.getOEBlocks(zd,
                            0, 8, 0, 8, norm, false, false, null, 0, 0,
                            ExtractingOEDataUtils.ThresholdType.TRUE_OE, 0, Float.NaN);
                        if (records.size() != 3) throw new AssertionError("missing trans records");
                        float[] counts = {1, 1, 5};
                        for (int i = 0; i < records.size(); i++) {
                            close(counts[i] / mean / (norm.equals(NormalizationHandler.NONE) ? 1 : product),
                                records.get(i).getCounts());
                        }
                        List<ContactRecord> window = ExtractingOEDataUtils.getOEBlocks(zd,
                            0, 1, 0, 1, norm, false, false, null, 0, 0,
                            ExtractingOEDataUtils.ThresholdType.TRUE_OE, 0, Float.NaN);
                        // Block-level queries may include extra cells; verify the requested cell.
                        boolean found = false;
                        for (ContactRecord r : window) if (r.getBinX() == 0 && r.getBinY() == 0) {
                            found = true;
                            close(1 / mean / (norm.equals(NormalizationHandler.NONE) ? 1 : product), r.getCounts());
                        }
                        if (!found) throw new AssertionError("missing requested trans cell");
                    }
                }
            }
        }
        checkScoreMeans(args[1]);
        System.out.println("V10 trans O/E: count/score, raw/normalized, derived, reversed, window, FRAG, invalid means passed");
    }

    private static void checkScoreMeans(String source) throws Exception {
        byte[] data = Files.readAllBytes(Path.of(source));
        ByteBuffer bytes = ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);
        int footer = (int) bytes.getLong(16);
        int matrix = (int) bytes.getLong(footer + 32);
        Path temporary = Files.createTempFile("java-straw-trans-mean-", ".hic");
        try {
            for (double sum : new double[]{0, Double.NaN, Double.POSITIVE_INFINITY, -7}) {
                bytes.putDouble(matrix + 44, sum);
                Files.write(temporary, data);
                Dataset dataset = HiCFileTools.extractDatasetForCLT(temporary.toString(), false, true, false);
                Chromosome[] chromosomes = dataset.getChromosomeHandler().getChromosomeArrayWithoutAllByAll();
                for (boolean reverse : new boolean[]{false, true}) {
                    MatrixZoomData zd = dataset.getMatrix(chromosomes[reverse ? 1 : 0], chromosomes[reverse ? 0 : 1])
                        .getZoomData(new HiCZoom(HiCZoom.HiCUnit.BP, 10));
                    List<ContactRecord> records = ExtractingOEDataUtils.getOEBlocks(zd, 0, 8, 0, 8,
                        NormalizationHandler.NONE, false, false, null, 0, 0,
                        ExtractingOEDataUtils.ThresholdType.TRUE_OE, 0, Float.NaN);
                    if (sum == -7) {
                        if (records.size() != 3) throw new AssertionError("negative mean rejected");
                        close(-8, records.get(0).getCounts());
                    } else if (!records.isEmpty()) throw new AssertionError("invalid trans mean accepted");
                }
            }
        } finally {
            Files.deleteIfExists(temporary);
        }
    }

    private static void close(double expected, double actual) {
        if (!Double.isFinite(actual) || Math.abs(expected - actual) > 1e-5) {
            throw new AssertionError("expected " + expected + ", got " + actual);
        }
    }
}
